<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{payload.storeName||effective.storeName||'商户申请详情'}}</h2><p>{{status(selected&&selected.kind)}} <StatusTag v-if="selected" :value="selected.status"/></p><p v-if="selected" class="ui-meta">申请 {{selected.id}} · 提交 v{{selected.revision}} · 当前提交 v{{selected.currentRevision}} · 数据 v{{selected.version}}</p></div><div class="ui-actions"><Button @click="back">返回申请列表</Button><Button @click="reload">重新读取</Button></div></header><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><template v-if="selected"><Alert v-if="selected.historical" type="warning" show-icon>只读历史版本。<Button type="text" @click="current">返回当前申请</Button></Alert><Tabs v-model="tab" :animated="false"><TabPane label="申请概览" name="overview"><DetailSection title="本次申请"><FieldRow label="申请类型" :value="status(selected.kind)"/><FieldRow label="当前状态" :value="status(selected.currentStatus)"/><FieldRow label="提交时间" :value="date(selected.submittedAt)"/><FieldRow label="更新时间" :value="date(selected.updatedAt)"/><FieldRow v-if="selected.storeId" label="关联商户" :value="selected.storeId"/><FieldRow v-if="selected.baseStoreVersion!=null" label="提交依据资料版本" :value="String(selected.baseStoreVersion)"/></DetailSection><p class="ui-note">准入审核不依赖真实收付通就绪；批准只处理当前选定提交版本。</p></TabPane><TabPane label="主体与经营信息" name="profile"><ProfileFields v-if="selected.kind!=='QUALIFICATION_CHANGE'" :profile="payload" purpose="admission" :range="false"/><ProfileFields v-else :profile="effective" purpose="admission" :range="false"/></TabPane><TabPane label="经营范围与资质" name="qualifications"><DetailSection title="本次提交范围" :grid="false"><CategoryNames :ids="payload.categoryIds||effective.categoryIds||[]" purpose="admission"/></DetailSection><QualificationTable :records="qualifications" purpose="admission"/></TabPane><TabPane v-if="selected.kind!=='ADMISSION'" label="本次变更" name="changes"><Alert show-icon>左侧是当前有效档案，右侧是本次提交快照；批准前不会覆盖有效资料。</Alert><div class="ui-comparison"><div><h3>当前有效资料 · v{{effective.version}}</h3><ProfileFields :profile="effective" purpose="admission"/><QualificationTable :records="effective.qualifications&&effective.qualifications.versions||[]" purpose="admission"/></div><div><h3>本次提交 · v{{selected.revision}}</h3><ProfileFields v-if="selected.kind==='PROFILE_CHANGE'" :profile="payload" purpose="admission"/><QualificationTable :records="qualifications" purpose="admission"/></div></div></TabPane><TabPane label="审核记录" name="history"><HistoryTable :records="selected.history" :columns="historyColumns"><template slot="operations" slot-scope="{row}"><Button size="small" @click="history(row.revision)">查看提交快照</Button></template></HistoryTable></TabPane></Tabs><footer class="ui-footer-actions"><span v-if="!reviewable" class="ui-meta">{{selected.historical?'历史版本只读':selected.currentStatus==='SUBMITTED'?'当前无审核权限':'仅当前待审版本可审批'}}</span><Button @click="back">返回列表</Button><Button v-if="reviewable" type="error" :disabled="blocked" @click="review(false)">驳回并填写原因</Button><Button v-if="reviewable" type="primary" :disabled="blocked" @click="review(true)">批准当前提交版本</Button></footer></template></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';import DetailSection from './components/DetailSection';import FieldRow from './components/FieldRow';import ProfileFields from './components/ProfileFields';import CategoryNames from './components/CategoryNames';import QualificationTable from './components/QualificationTable';import HistoryTable from './components/HistoryTable';export default {mixins:[page],components:{PageStatus,StatusTag,DetailSection,FieldRow,ProfileFields,CategoryNames,QualificationTable,HistoryTable},data:()=>({historyColumns:[{title:'提交版本',key:'revision',width:100},{title:'状态',slot:'state',width:110},{title:'审核人',key:'reviewerName',minWidth:140},{title:'时间（上海）',slot:'time',minWidth:180},{title:'意见',key:'reason',minWidth:200},{title:'操作',slot:'operations',width:150}]}),computed:{payload(){return this.selected&&this.selected.payload||{};},effective(){return this.selected&&this.selected.currentEffective||{};},reviewable(){return this.selected&&!this.selected.historical&&this.selected.currentStatus==='SUBMITTED'&&this.can('admission.review');},qualifications(){const values=this.payload.qualifications||[];return values.map((q,i)=>({id:q.id||'submitted-'+i,revision:this.selected.revision,status:this.selected.status,scope:q.categoryIds&&q.categoryIds.length?'CATEGORY':'STORE',type:q.type,categoryIds:q.categoryIds||[],longTerm:q.longTerm,validFrom:q.validFrom,validTo:q.validThrough,details:q}));}},watch:{'$route.fullPath'(){this.tab='overview';this.reload();}},mounted(){this.reload();},methods:{reload(){return this.latest(()=>this.ui('/applications/'+this.$route.params.id,{revision:this.$route.query.revision||undefined}),v=>{this.selected=v;},()=>{this.selected=null;});},history(revision){this.$router.push({path:this.$route.path,query:{...this.$route.query,revision:String(revision)}});},current(){const query={...this.$route.query};delete query.revision;this.$router.replace({path:this.$route.path,query});},async review(approve){const row=this.selected;if(!this.reviewable)return;const value=await this.command('/applications/'+row.id+(approve?'/approve':'/reject'),approve?'批准当前提交版本':'驳回当前提交版本',{expectedVersion:row.version,revision:row.currentRevision},(this.payload.storeName||this.effective.storeName||'当前商户')+' · 提交 v'+row.currentRevision+'。'+(approve?'入驻将建立唯一经营授权；资料变更只生效被审版本。':'驳回保留当前有效资料，申请人可以修订重提。'));if(value)await this.reload();}}};</script>
